-- ===========================================================================
-- Annapurna Stores -- operational master data  (load into PostgreSQL)
--   psql -h localhost -U annapurna -d annapurna -f masters.sql
--
-- NOTE FROM THE BILLING VENDOR:  products.product_code is NOT unique.
-- A handful of codes were retired and later reissued to a different
-- product.  Use (product_code, valid_from..valid_to) to identify a
-- product, or better, join on the surrogate key product_sk.
-- ===========================================================================

DROP TABLE IF EXISTS price_revisions CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS product_categories CASCADE;
DROP TABLE IF EXISTS stores CASCADE;

CREATE TABLE stores (
    store_id         TEXT PRIMARY KEY,
    store_name       TEXT NOT NULL,
    address_line     TEXT NOT NULL,
    city             TEXT NOT NULL,
    state            TEXT NOT NULL,
    region           TEXT NOT NULL,
    floor_area_sqft  INTEGER NOT NULL,
    opened_on        DATE NOT NULL
);

CREATE TABLE product_categories (
    category_id   TEXT PRIMARY KEY,
    category_name TEXT NOT NULL,
    department    TEXT NOT NULL,
    gst_rate      NUMERIC(4,3) NOT NULL
);

CREATE TABLE products (
    product_sk    BIGINT PRIMARY KEY,          -- surrogate key: 1 row = 1 real product
    product_code  TEXT NOT NULL,               -- NOT UNIQUE.  see note above.
    product_name  TEXT NOT NULL,
    category_id   TEXT NOT NULL REFERENCES product_categories(category_id),
    brand         TEXT,
    pack_size     TEXT,
    uom           TEXT,
    valid_from    DATE NOT NULL,
    valid_to      DATE NOT NULL DEFAULT DATE '9999-12-31',
    is_current    BOOLEAN NOT NULL
);
CREATE INDEX ix_products_code       ON products(product_code);
CREATE INDEX ix_products_code_valid ON products(product_code, valid_from, valid_to);

CREATE TABLE price_revisions (
    revision_id    BIGINT PRIMARY KEY,
    product_sk     BIGINT NOT NULL REFERENCES products(product_sk),
    mrp            NUMERIC(12,2) NOT NULL,
    selling_price  NUMERIC(12,2) NOT NULL,
    effective_from DATE NOT NULL,
    effective_to   DATE NOT NULL DEFAULT DATE '9999-12-31'
);
CREATE INDEX ix_pricerev_sk_from ON price_revisions(product_sk, effective_from);

